insert into public.chapters(id,sort,emoji,color,name_en,name_nl,range_en,range_nl) values ('universe',0,'🌌','#7b6cff','The Universe','Het heelal','13.8 – 4.6 billion years ago','13,8 – 4,6 miljard jaar geleden') on conflict (id) do nothing;
