insert into public.chapters(id,sort,emoji,color,name_en,name_nl,range_en,range_nl) values ('humans',2,'🦴','#d98e4a','Early Humans','Vroege mensen','300,000 years ago – 10,000 BCE','300.000 jaar geleden – 10.000 v.Chr.') on conflict (id) do nothing;
insert into public.chapters(id,sort,emoji,color,name_en,name_nl,range_en,range_nl) values ('first',3,'🏺','#e0b341','First Civilizations','Eerste beschavingen','3500 – 1900 BCE','3500 – 1900 v.Chr.') on conflict (id) do nothing;
insert into public.chapters(id,sort,emoji,color,name_en,name_nl,range_en,range_nl) values ('classical',4,'🏛️','#ef6f6c','The Classical World','De klassieke wereld','508 BCE – 476 CE','508 v.Chr. – 476 n.Chr.') on conflict (id) do nothing;
insert into public.chapters(id,sort,emoji,color,name_en,name_nl,range_en,range_nl) values ('medieval',5,'🏰','#9b6bd6','The Middle Ages','De middeleeuwen','476 – 1450','476 – 1450') on conflict (id) do nothing;
insert into public.chapters(id,sort,emoji,color,name_en,name_nl,range_en,range_nl) values ('early',6,'🧭','#3ea0e8','Early Modern Era','Vroegmoderne tijd','1450 – 1800','1450 – 1800') on conflict (id) do nothing;
insert into public.chapters(id,sort,emoji,color,name_en,name_nl,range_en,range_nl) values ('modern',7,'🏭','#4cc56f','The Modern World','De moderne wereld','1800 – today','1800 – vandaag') on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('u1','universe',0,'{"w":"13.8 billion years ago","ti":"The Big Bang","tx":"The universe began about 13.8 billion years ago from an extremely hot, dense state and has been expanding ever since. Within minutes it formed the first atomic nuclei, mostly hydrogen and helium.","q":"How old is the universe?","o":["About 13.8 billion years","About 4.6 billion years","About 100 million years","About 1 trillion years"],"x":"Measurements of the cosmic microwave background give about 13.8 billion years."}'::jsonb,'{"w":"13,8 miljard jaar geleden","ti":"De oerknal","tx":"Het heelal ontstond ongeveer 13,8 miljard jaar geleden uit een extreem hete, dichte toestand en dijt sindsdien uit. Binnen enkele minuten ontstonden de eerste atoomkernen, vooral waterstof en helium.","q":"Hoe oud is het heelal?","o":["Ongeveer 13,8 miljard jaar","Ongeveer 4,6 miljard jaar","Ongeveer 100 miljoen jaar","Ongeveer 1 biljoen jaar"],"x":"Metingen van de kosmische achtergrondstraling geven ongeveer 13,8 miljard jaar."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('u2','universe',1,'{"w":"Over 13 billion years ago","ti":"First stars and galaxies","tx":"The first stars lit up within a few hundred million years after the Big Bang. Inside stars and in supernova explosions, heavier elements like carbon, oxygen and iron were forged.","q":"Where were elements heavier than hydrogen and helium mostly made?","o":["Inside stars and supernovae","In the Big Bang itself","In black holes only","On planets"],"x":"Fusion in stars and supernova explosions created most heavier elements. We are made of star dust."}'::jsonb,'{"w":"Meer dan 13 miljard jaar geleden","ti":"Eerste sterren en sterrenstelsels","tx":"De eerste sterren gingen aan binnen enkele honderden miljoenen jaren na de oerknal. In sterren en bij supernova-explosies ontstonden zwaardere elementen zoals koolstof, zuurstof en ijzer.","q":"Waar ontstonden de elementen zwaarder dan waterstof en helium grotendeels?","o":["In sterren en supernova''s","In de oerknal zelf","Enkel in zwarte gaten","Op planeten"],"x":"Kernfusie in sterren en supernova-explosies maakte de meeste zwaardere elementen. Wij zijn gemaakt van sterrenstof."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('u3','universe',2,'{"w":"4.6 billion years ago","ti":"Birth of the Solar System","tx":"A cloud of gas and dust collapsed under gravity. The Sun formed at the centre and the planets formed from the leftover disc.","q":"How old is the Solar System?","o":["About 4.6 billion years","About 13.8 billion years","About 1 billion years","About 500 million years"],"x":"Dating of meteorites gives about 4.6 billion years."}'::jsonb,'{"w":"4,6 miljard jaar geleden","ti":"Geboorte van het zonnestelsel","tx":"Een wolk van gas en stof stortte in door zwaartekracht. De zon ontstond in het midden en de planeten uit de overgebleven schijf.","q":"Hoe oud is het zonnestelsel?","o":["Ongeveer 4,6 miljard jaar","Ongeveer 13,8 miljard jaar","Ongeveer 1 miljard jaar","Ongeveer 500 miljoen jaar"],"x":"Datering van meteorieten geeft ongeveer 4,6 miljard jaar."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('e1','earth',3,'{"w":"4.54 billion years ago","ti":"Earth and the Moon","tx":"Earth formed about 4.54 billion years ago. The leading theory says the Moon formed soon after, when a Mars-sized body hit the young Earth.","q":"How did the Moon most likely form?","o":["A Mars-sized body hit the young Earth","A passing comet was captured by Earth","It split off from Mars","It formed from solar flares"],"x":"The giant-impact hypothesis best explains the Moon''s composition."}'::jsonb,'{"w":"4,54 miljard jaar geleden","ti":"Aarde en maan","tx":"De aarde ontstond ongeveer 4,54 miljard jaar geleden. Volgens de meest aanvaarde theorie ontstond de maan kort daarna toen een object ter grootte van Mars de jonge aarde raakte.","q":"Hoe ontstond de maan waarschijnlijk?","o":["Een object ter grootte van Mars raakte de jonge aarde","Een voorbijkomende komeet werd ingevangen","Ze brak af van Mars","Ze ontstond uit zonnevlammen"],"x":"De ''giant impact''-hypothese verklaart de samenstelling van de maan het best."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('e2','earth',4,'{"w":"3.5–3.8 billion years ago","ti":"The first life","tx":"The oldest traces of life are single-celled microbes in the oceans. For billions of years life stayed microscopic.","q":"What were the first living things?","o":["Single-celled microorganisms","Small fish","Plants","Insects"],"x":"Fossils and chemical traces show microbial life at least 3.5 billion years ago."}'::jsonb,'{"w":"3,5–3,8 miljard jaar geleden","ti":"Het eerste leven","tx":"De oudste sporen van leven zijn eencellige microben in de oceanen. Miljarden jaren bleef leven microscopisch klein.","q":"Wat waren de eerste levende wezens?","o":["Eencellige micro-organismen","Kleine vissen","Planten","Insecten"],"x":"Fossielen en chemische sporen tonen microbieel leven minstens 3,5 miljard jaar geleden."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('e3','earth',5,'{"w":"About 2.4 billion years ago","ti":"The Great Oxidation","tx":"Cyanobacteria began producing oxygen by photosynthesis. Oxygen built up in the atmosphere, changing Earth''s chemistry and making complex life possible later.","q":"Which organisms first filled the air with oxygen?","o":["Cyanobacteria","Dinosaurs","Trees","Fungi"],"x":"Photosynthesising cyanobacteria caused the Great Oxidation Event."}'::jsonb,'{"w":"Ongeveer 2,4 miljard jaar geleden","ti":"De grote oxidatie","tx":"Cyanobacteriën begonnen zuurstof te produceren via fotosynthese. Zuurstof hoopte zich op in de atmosfeer, veranderde de chemie van de aarde en maakte later complex leven mogelijk.","q":"Welke organismen vulden de lucht als eerste met zuurstof?","o":["Cyanobacteriën","Dinosauriërs","Bomen","Schimmels"],"x":"Fotosynthetiserende cyanobacteriën veroorzaakten de grote oxidatie."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('e4','earth',6,'{"w":"66 million years ago","ti":"The end of the dinosaurs","tx":"Non-avian dinosaurs ruled the land for over 150 million years. An asteroid impact at Chicxulub (Mexico) about 66 million years ago caused a mass extinction. Birds are their living descendants.","q":"When did the non-avian dinosaurs die out?","o":["66 million years ago","6.6 million years ago","660 million years ago","6,000 years ago"],"x":"The Chicxulub impact marks the end of the Cretaceous, 66 million years ago."}'::jsonb,'{"w":"66 miljoen jaar geleden","ti":"Het einde van de dinosauriërs","tx":"Dinosauriërs (behalve vogels) domineerden het land meer dan 150 miljoen jaar. Een asteroïde-inslag bij Chicxulub (Mexico) zo''n 66 miljoen jaar geleden veroorzaakte een massauitsterving. Vogels zijn hun levende nakomelingen.","q":"Wanneer stierven de dinosauriërs (behalve vogels) uit?","o":["66 miljoen jaar geleden","6,6 miljoen jaar geleden","660 miljoen jaar geleden","6.000 jaar geleden"],"x":"De inslag bij Chicxulub markeert het einde van het Krijt, 66 miljoen jaar geleden."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('h1','humans',7,'{"w":"About 300,000 years ago","ti":"Homo sapiens appears","tx":"Our species evolved in Africa. The oldest known Homo sapiens fossils, from Jebel Irhoud in Morocco, are about 300,000 years old.","q":"Where did Homo sapiens first appear?","o":["Africa","Europe","Asia","Australia"],"x":"The oldest fossils of our species come from Africa."}'::jsonb,'{"w":"Ongeveer 300.000 jaar geleden","ti":"Homo sapiens verschijnt","tx":"Onze soort ontstond in Afrika. De oudst bekende fossielen van Homo sapiens, uit Jebel Irhoud in Marokko, zijn ongeveer 300.000 jaar oud.","q":"Waar verscheen Homo sapiens voor het eerst?","o":["Afrika","Europa","Azië","Australië"],"x":"De oudste fossielen van onze soort komen uit Afrika."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('h2','humans',8,'{"w":"70,000–60,000 years ago","ti":"Out of Africa","tx":"The main dispersal of modern humans out of Africa happened roughly 70,000–60,000 years ago. They spread across Asia, reached Australia, and later Europe and the Americas.","q":"Roughly when did the main spread of modern humans out of Africa happen?","o":["70,000–60,000 years ago","7,000 years ago","700,000 years ago","2,000 years ago"],"x":"Genetic evidence points to a major dispersal around 70,000–60,000 years ago."}'::jsonb,'{"w":"70.000–60.000 jaar geleden","ti":"Uit Afrika","tx":"De belangrijkste verspreiding van moderne mensen uit Afrika gebeurde ruwweg 70.000–60.000 jaar geleden. Ze verspreidden zich over Azië, bereikten Australië en later Europa en Amerika.","q":"Wanneer vond de belangrijkste verspreiding van moderne mensen uit Afrika ongeveer plaats?","o":["70.000–60.000 jaar geleden","7.000 jaar geleden","700.000 jaar geleden","2.000 jaar geleden"],"x":"Genetisch bewijs wijst op een grote migratie rond 70.000–60.000 jaar geleden."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('h3','humans',9,'{"w":"About 10,000 BCE","ti":"The Neolithic Revolution","tx":"After the last Ice Age, people in the Fertile Crescent began growing crops and domesticating animals. Hunter-gatherers became farmers living in permanent villages.","q":"What defined the Neolithic Revolution?","o":["The start of farming and settled life","The invention of the wheel","The first use of iron","The first writing"],"x":"Farming allowed food surplus, villages and eventually cities."}'::jsonb,'{"w":"Rond 10.000 v.Chr.","ti":"De neolithische revolutie","tx":"Na de laatste ijstijd begonnen mensen in de Vruchtbare Halvemaan gewassen te telen en dieren te domesticeren. Jagers-verzamelaars werden boeren in vaste dorpen.","q":"Wat kenmerkte de neolithische revolutie?","o":["Het begin van landbouw en vaste woonplaatsen","De uitvinding van het wiel","Het eerste gebruik van ijzer","Het eerste schrift"],"x":"Landbouw zorgde voor voedseloverschotten, dorpen en uiteindelijk steden."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('c1','first',10,'{"w":"About 3500–3000 BCE","ti":"Sumer: the first cities","tx":"In southern Mesopotamia, between the Tigris and Euphrates, the Sumerians built cities like Uruk. Around 3200 BCE they developed cuneiform, one of the earliest writing systems.","q":"What was the Sumerian writing system called?","o":["Cuneiform","Hieroglyphs","The Latin alphabet","Runes"],"x":"Cuneiform: wedge-shaped marks pressed into clay."}'::jsonb,'{"w":"Rond 3500–3000 v.Chr.","ti":"Sumerië: de eerste steden","tx":"In Zuid-Mesopotamië, tussen Tigris en Eufraat, bouwden de Sumeriërs steden zoals Uruk. Rond 3200 v.Chr. ontwikkelden ze het spijkerschrift, een van de oudste schriftsystemen.","q":"Hoe heette het Sumerische schriftsysteem?","o":["Spijkerschrift","Hiërogliefen","Het Latijnse alfabet","Runen"],"x":"Spijkerschrift: wigvormige tekens gedrukt in klei."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('c2','first',11,'{"w":"About 3100–2500 BCE","ti":"Ancient Egypt","tx":"Egypt was united around 3100 BCE under a pharaoh. The Great Pyramid of Giza, built about 2600–2500 BCE for pharaoh Khufu, was the tallest human-made structure for about 3,800 years.","q":"For which pharaoh was the Great Pyramid of Giza built?","o":["Khufu","Tutankhamun","Ramses II","Cleopatra"],"x":"Khufu (Cheops) of the 4th dynasty."}'::jsonb,'{"w":"Rond 3100–2500 v.Chr.","ti":"Het oude Egypte","tx":"Egypte werd rond 3100 v.Chr. verenigd onder een farao. De Grote Piramide van Gizeh, gebouwd rond 2600–2500 v.Chr. voor farao Choefoe, was zo''n 3.800 jaar lang het hoogste door mensen gebouwde bouwwerk.","q":"Voor welke farao werd de Grote Piramide van Gizeh gebouwd?","o":["Choefoe","Toetanchamon","Ramses II","Cleopatra"],"x":"Choefoe (Cheops) van de 4e dynastie."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('c3','first',12,'{"w":"About 2600–1900 BCE","ti":"The Indus Valley Civilization","tx":"Along the Indus River, cities like Harappa and Mohenjo-daro had planned streets, brick houses and drainage systems. Their script is still undeciphered.","q":"Which two cities belonged to the Indus Valley Civilization?","o":["Harappa and Mohenjo-daro","Uruk and Ur","Memphis and Thebes","Athens and Sparta"],"x":"Harappa and Mohenjo-daro are its best-known cities."}'::jsonb,'{"w":"Rond 2600–1900 v.Chr.","ti":"De Indusbeschaving","tx":"Langs de Indus hadden steden als Harappa en Mohenjo-daro geplande straten, bakstenen huizen en riolering. Hun schrift is nog steeds niet ontcijferd.","q":"Welke twee steden behoorden tot de Indusbeschaving?","o":["Harappa en Mohenjo-daro","Uruk en Ur","Memphis en Thebe","Athene en Sparta"],"x":"Harappa en Mohenjo-daro zijn de bekendste steden."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('k1','classical',13,'{"w":"508 BCE","ti":"Athenian democracy","tx":"In 508 BCE the reformer Cleisthenes introduced a system in Athens where male citizens voted directly on laws. It is seen as the first democracy, though women, slaves and foreigners were excluded.","q":"Which city-state is known for the first democracy?","o":["Athens","Sparta","Corinth","Thebes"],"x":"Athens, around 508 BCE."}'::jsonb,'{"w":"508 v.Chr.","ti":"Atheense democratie","tx":"In 508 v.Chr. voerde hervormer Cleisthenes in Athene een systeem in waarbij mannelijke burgers rechtstreeks over wetten stemden. Het geldt als de eerste democratie, al waren vrouwen, slaven en vreemdelingen uitgesloten.","q":"Welke stadstaat staat bekend voor de eerste democratie?","o":["Athene","Sparta","Korinthe","Thebe"],"x":"Athene, rond 508 v.Chr."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('k2','classical',14,'{"w":"27 BCE – 476 CE","ti":"The Roman Empire","tx":"Rome grew from a city into a republic and then an empire; Augustus became the first emperor in 27 BCE. The Western Roman Empire ended in 476 CE; the Eastern half (Byzantium) lasted until 1453.","q":"In which year is the fall of the Western Roman Empire traditionally dated?","o":["476 CE","27 BCE","1066 CE","800 CE"],"x":"476 CE, when Odoacer deposed Romulus Augustulus."}'::jsonb,'{"w":"27 v.Chr. – 476 n.Chr.","ti":"Het Romeinse Rijk","tx":"Rome groeide van stad tot republiek en daarna keizerrijk; Augustus werd in 27 v.Chr. de eerste keizer. Het West-Romeinse Rijk eindigde in 476 n.Chr.; de oostelijke helft (Byzantium) bestond tot 1453.","q":"In welk jaar situeert men traditioneel de val van het West-Romeinse Rijk?","o":["476 n.Chr.","27 v.Chr.","1066 n.Chr.","800 n.Chr."],"x":"476 n.Chr., toen Odoaker Romulus Augustulus afzette."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('k3','classical',15,'{"w":"206 BCE – 220 CE","ti":"Han China and the Silk Road","tx":"The Han dynasty ruled a large, centralised China and opened trade routes westward. Along the Silk Road, silk, spices, ideas and diseases travelled between China and the Mediterranean.","q":"What was the trade network linking China with the Mediterranean called?","o":["The Silk Road","The Amber Road","The Spice Strait","The Royal Road"],"x":"The Silk Road, a network of overland and sea routes."}'::jsonb,'{"w":"206 v.Chr. – 220 n.Chr.","ti":"Han-China en de Zijderoute","tx":"De Han-dynastie regeerde een groot, gecentraliseerd China en opende handelsroutes naar het westen. Langs de Zijderoute reisden zijde, specerijen, ideeën en ziektes tussen China en het Middellandse Zeegebied.","q":"Hoe heette het handelsnetwerk tussen China en het Middellandse Zeegebied?","o":["De Zijderoute","De Barnsteenroute","De Specerijenzee","De Koningsweg"],"x":"De Zijderoute, een netwerk van land- en zeeroutes."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('m1','medieval',16,'{"w":"8th–13th century","ti":"The Islamic Golden Age","tx":"In Baghdad''s House of Wisdom, scholars translated and extended Greek, Persian and Indian knowledge. Al-Khwarizmi''s book on al-jabr gave us the word ''algebra'', and his name gave us ''algorithm''.","q":"Which word comes from al-Khwarizmi''s term ''al-jabr''?","o":["Algebra","Algorithm","Alcohol","Almanac"],"x":"''Al-jabr'' became ''algebra''. ''Algorithm'' comes from his name."}'::jsonb,'{"w":"8e–13e eeuw","ti":"De Islamitische Gouden Eeuw","tx":"In het Huis van Wijsheid in Bagdad vertaalden en vernieuwden geleerden Griekse, Perzische en Indische kennis. Al-Chwarizmi''s boek over al-jabr gaf ons het woord ''algebra'', en zijn naam het woord ''algoritme''.","q":"Welk woord komt van al-Chwarizmi''s term ''al-jabr''?","o":["Algebra","Algoritme","Alcohol","Almanak"],"x":"''Al-jabr'' werd ''algebra''. ''Algoritme'' komt van zijn naam."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('m2','medieval',17,'{"w":"800 CE","ti":"Charlemagne and feudal Europe","tx":"On Christmas Day 800, Pope Leo III crowned Charlemagne emperor, reviving the idea of a Western empire. After his empire split, Europe was organised in feudalism: lords, vassals and peasants.","q":"In which year was Charlemagne crowned emperor?","o":["800","476","1066","1492"],"x":"Christmas Day, 800."}'::jsonb,'{"w":"800 n.Chr.","ti":"Karel de Grote en het feodale Europa","tx":"Op Kerstdag 800 kroonde paus Leo III Karel de Grote tot keizer, waarmee het idee van een westers keizerrijk herleefde. Na de opdeling van zijn rijk werd Europa georganiseerd als feodaal stelsel: heren, vazallen en boeren.","q":"In welk jaar werd Karel de Grote tot keizer gekroond?","o":["800","476","1066","1492"],"x":"Kerstdag 800."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('m3','medieval',18,'{"w":"1347–1351","ti":"The Black Death","tx":"The plague spread from Asia along trade routes and reached Europe in 1347. It killed an estimated third or more of Europe''s population.","q":"Roughly what share of Europe''s population died in the Black Death?","o":["A third or more","About 1%","About 5%","Nearly everyone"],"x":"Estimates range from about a third to a half."}'::jsonb,'{"w":"1347–1351","ti":"De Zwarte Dood","tx":"De pest verspreidde zich vanuit Azië langs handelsroutes en bereikte Europa in 1347. Naar schatting stierf een derde of meer van de Europese bevolking.","q":"Welk aandeel van de Europese bevolking stierf ongeveer aan de Zwarte Dood?","o":["Een derde of meer","Ongeveer 1%","Ongeveer 5%","Bijna iedereen"],"x":"Schattingen lopen van ongeveer een derde tot de helft."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('r1','early',19,'{"w":"Around 1450","ti":"The printing press","tx":"Around 1450 Johannes Gutenberg in Mainz developed printing with movable metal type in Europe. Books became cheaper and ideas spread faster, fuelling the Renaissance, the Reformation and science.","q":"Who developed the European printing press with movable type?","o":["Johannes Gutenberg","Leonardo da Vinci","Martin Luther","Isaac Newton"],"x":"Gutenberg, in Mainz, around 1450."}'::jsonb,'{"w":"Rond 1450","ti":"De drukpers","tx":"Rond 1450 ontwikkelde Johannes Gutenberg in Mainz de drukpers met losse metalen letters in Europa. Boeken werden goedkoper en ideeën verspreidden sneller, wat renaissance, reformatie en wetenschap voedde.","q":"Wie ontwikkelde de Europese drukpers met losse letters?","o":["Johannes Gutenberg","Leonardo da Vinci","Maarten Luther","Isaac Newton"],"x":"Gutenberg, in Mainz, rond 1450."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('r2','early',20,'{"w":"1492–1522","ti":"The Age of Exploration","tx":"Columbus reached the Americas in 1492, Vasco da Gama sailed to India in 1498, and Magellan''s expedition completed the first circumnavigation of the globe (1519–1522). Contact between continents reshaped the world, with devastating effects on Indigenous peoples.","q":"In which year did Columbus first reach the Americas?","o":["1492","1453","1519","1607"],"x":"1492. People had already lived in the Americas for more than 15,000 years."}'::jsonb,'{"w":"1492–1522","ti":"Het tijdperk van de ontdekkingen","tx":"Columbus bereikte Amerika in 1492, Vasco da Gama zeilde in 1498 naar India en de expeditie van Magellaan voltooide de eerste omzeiling van de wereld (1519–1522). Het contact tussen continenten veranderde de wereld, met verwoestende gevolgen voor de inheemse bevolking.","q":"In welk jaar bereikte Columbus voor het eerst Amerika?","o":["1492","1453","1519","1607"],"x":"1492. Mensen woonden er toen al meer dan 15.000 jaar."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('r3','early',21,'{"w":"1543–1687","ti":"The Scientific Revolution","tx":"In 1543 Copernicus proposed that the Earth orbits the Sun. Galileo, Kepler and finally Newton (Principia, 1687) showed that nature follows mathematical laws.","q":"Who published the Sun-centred model of the universe in 1543?","o":["Copernicus","Ptolemy","Aristotle","Darwin"],"x":"Nicolaus Copernicus, in De revolutionibus."}'::jsonb,'{"w":"1543–1687","ti":"De wetenschappelijke revolutie","tx":"In 1543 stelde Copernicus dat de aarde rond de zon draait. Galilei, Kepler en uiteindelijk Newton (Principia, 1687) toonden aan dat de natuur wiskundige wetten volgt.","q":"Wie publiceerde in 1543 het zonnecentrische model?","o":["Copernicus","Ptolemaeus","Aristoteles","Darwin"],"x":"Nicolaus Copernicus, in De revolutionibus."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('r4','early',22,'{"w":"1776–1789","ti":"Enlightenment and revolutions","tx":"Enlightenment thinkers argued for reason, rights and liberty. The American Revolution (1776) and the French Revolution (1789) turned these ideas into new republics.","q":"In which year did the French Revolution begin?","o":["1789","1776","1815","1848"],"x":"1789, with the storming of the Bastille."}'::jsonb,'{"w":"1776–1789","ti":"Verlichting en revoluties","tx":"Verlichtingsdenkers pleitten voor rede, rechten en vrijheid. De Amerikaanse (1776) en de Franse Revolutie (1789) zetten die ideeën om in nieuwe republieken.","q":"In welk jaar begon de Franse Revolutie?","o":["1789","1776","1815","1848"],"x":"1789, met de bestorming van de Bastille."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('n1','modern',23,'{"w":"About 1760–1840","ti":"The Industrial Revolution","tx":"Starting in Britain, steam engines and factories transformed production, transport and cities. Population and wealth grew rapidly, and so did pollution. Belgium was the first country on the continent to follow.","q":"In which country did the Industrial Revolution begin?","o":["Britain","France","Germany","The United States"],"x":"Britain, with coal, steam power and textile mills."}'::jsonb,'{"w":"Ongeveer 1760–1840","ti":"De industriële revolutie","tx":"Vanuit Groot-Brittannië veranderden stoommachines en fabrieken productie, transport en steden. Bevolking en welvaart groeiden snel, en de vervuiling ook. België was het eerste land op het continent dat volgde.","q":"In welk land begon de industriële revolutie?","o":["Groot-Brittannië","Frankrijk","Duitsland","De Verenigde Staten"],"x":"Groot-Brittannië, met steenkool, stoomkracht en textielfabrieken."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('n2','modern',24,'{"w":"1914–1945","ti":"The World Wars","tx":"World War I (1914–1918) and World War II (1939–1945) caused tens of millions of deaths and redrew the world map. After 1945 the United Nations was founded to keep peace.","q":"In which year did World War II end?","o":["1945","1918","1939","1950"],"x":"1945."}'::jsonb,'{"w":"1914–1945","ti":"De wereldoorlogen","tx":"De Eerste (1914–1918) en Tweede Wereldoorlog (1939–1945) eisten tientallen miljoenen levens en tekenden de wereldkaart opnieuw. Na 1945 werden de Verenigde Naties opgericht om de vrede te bewaren.","q":"In welk jaar eindigde de Tweede Wereldoorlog?","o":["1945","1918","1939","1950"],"x":"1945."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,chapter,sort,en,nl) values ('n3','modern',25,'{"w":"1969 – today","ti":"The digital age","tx":"Humans first walked on the Moon in 1969. Tim Berners-Lee invented the World Wide Web at CERN around 1989–1991, and the internet and AI now shape daily life.","q":"Who invented the World Wide Web?","o":["Tim Berners-Lee","Bill Gates","Steve Jobs","Alan Turing"],"x":"Tim Berners-Lee, at CERN in Switzerland."}'::jsonb,'{"w":"1969 – vandaag","ti":"Het digitale tijdperk","tx":"In 1969 betraden mensen voor het eerst de maan. Tim Berners-Lee vond rond 1989–1991 het World Wide Web uit bij CERN, en internet en AI bepalen nu het dagelijks leven.","q":"Wie vond het World Wide Web uit?","o":["Tim Berners-Lee","Bill Gates","Steve Jobs","Alan Turing"],"x":"Tim Berners-Lee, bij CERN in Zwitserland."}'::jsonb) on conflict (id) do nothing;
